#[unsafe(export_name = "destack.fs.attrs.access")]
pub unsafe extern "C" fn destack_fs_attrs_access(path: OsPath, mode: AccessMode) -> RuntimeStatus {
    native_call(|context| {
        let _ = (&path, &mode);

        let world = context.check_and_resolve_world(FS_ATTRS_ACCESS)?;
        destack_fs_attrs_access_replay(context, world, path, mode)
    })
}

